# Auto-dial a PPPoE connection, with retries.
# Connection settings come from config.ps1 (generated by install.ps1).
$ErrorActionPreference = 'SilentlyContinue'
try { (Get-Process -Id $PID).PriorityClass = 'BelowNormal' } catch { }
$credFile   = Join-Path $PSScriptRoot 'cred.dat'
$logFile    = Join-Path $PSScriptRoot 'dial.log'
$configFile = Join-Path $PSScriptRoot 'config.ps1'
$maxTries  = 12
$retryWait = 5

function Write-Log([string]$msg) {
    if (-not $script:logChecked) {
        $script:logChecked = $true
        if ((Test-Path $logFile) -and (Get-Item $logFile).Length -gt 524288) {
            Move-Item $logFile "$logFile.old" -Force
        }
    }
    '{0}  {1}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg | Add-Content -Path $logFile
}

function Test-PppOnline {
    $iface = Get-NetIPInterface -InterfaceAlias $connName -AddressFamily IPv4 -ErrorAction SilentlyContinue
    return [bool]($iface -and $iface.ConnectionState -eq 'Connected')
}

if (-not (Test-Path $configFile)) { Write-Log 'ERROR: config.ps1 not found'; exit 1 }
. $configFile
if (-not $connName -or -not $userName) { Write-Log 'ERROR: config.ps1 missing $connName or $userName'; exit 1 }

if (-not (Test-Path $credFile)) { Write-Log 'ERROR: cred.dat not found'; exit 1 }

try {
    $sec  = ConvertTo-SecureString ((Get-Content $credFile -Raw).Trim())
    $bstr = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($sec)
    $plainPwd = [Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr)
    [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr)
} catch {
    Write-Log 'ERROR: failed to decrypt cred.dat'; exit 1
}

# wait for the NIC to settle only shortly after boot; reconnect checks run immediately
$tc = [Environment]::TickCount
if ($tc -ge 0 -and $tc -lt 120000) { Start-Sleep -Seconds 3 }

for ($try = 1; $try -le $maxTries; $try++) {
    if (Test-PppOnline) { Write-Log "online (check $try), nothing to do"; exit 0 }
    rasdial $connName $userName $plainPwd | Out-Null
    $code = $LASTEXITCODE
    Start-Sleep -Seconds 2
    if (Test-PppOnline) { Write-Log "dial OK on try $try"; exit 0 }
    Write-Log "dial fail on try $try (rasdial exit $code)"
    Start-Sleep -Seconds $retryWait
}

Write-Log 'GAVE UP: all retries failed'
exit 1
